using System.Collections.Generic;
using System.IO;
using System.Linq;
using Gearbound.Core;
using NUnit.Framework;

namespace Gearbound.Tests
{
    /// <summary>Checks the C# rules against fixtures generated by tools/simulation/reference_rules.py.</summary>
    public sealed class SharedRulesTests
    {
        private static string SharedPath(string relative)
        {
            var dir = new DirectoryInfo(Directory.GetCurrentDirectory());
            while (dir != null && !Directory.Exists(Path.Combine(dir.FullName, "shared"))) dir = dir.Parent;
            Assert.IsNotNull(dir, "Could not locate the repository's shared/ folder.");
            return Path.Combine(dir.FullName, "shared", relative);
        }

        private static string Read(string relative) => File.ReadAllText(SharedPath(relative));
        private static Dictionary<string, object> Fixture(string name) => SharedJson.Obj(SharedJson.Parse(Read("test-fixtures/" + name)), name);

        [Test]
        public void RandomMatchesSharedVectors()
        {
            var fixture = Fixture("random_vectors.json");
            foreach (var item in SharedJson.Arr(fixture, "nextUintCases"))
            {
                var c = SharedJson.Obj(item, "case");
                var rng = new SeededRandom((uint)SharedJson.Long(c, "seed"));
                var expected = SharedJson.Arr(c, "nextUint").Select(v => (uint)(long)v).ToArray();
                CollectionAssert.AreEqual(expected, Enumerable.Range(0, expected.Length).Select(_ => rng.NextUint()).ToArray());
            }
            var intCase = SharedJson.Obj(fixture["nextIntCase"], "nextIntCase");
            var r = new SeededRandom((uint)SharedJson.Long(intCase, "seed"));
            var actual = SharedJson.Arr(intCase, "bounds").Select(b => r.NextInt((int)(long)b)).ToArray();
            CollectionAssert.AreEqual(SharedJson.Arr(intCase, "results").Select(v => (int)(long)v).ToArray(), actual);
            Assert.AreEqual(8, r.Draws, "NextInt must consume exactly one draw per call.");
        }

        [Test]
        public void ShopRollsMatchSharedFixture()
        {
            var catalog = SharedDataLoader.LoadGears(Read("gears/starter_gears.json"));
            var config = SharedDataLoader.LoadShop(Read("economy/shop.json"));
            var fixture = Fixture("shop_cases.json");
            CollectionAssert.AreEqual(SharedJson.Arr(fixture, "rerollCosts").Select(v => (int)(long)v).ToArray(),
                Enumerable.Range(0, 7).Select(k => GearShop.RerollCost(config, k)).ToArray());

            foreach (var item in SharedJson.Arr(fixture, "cases"))
            {
                var c = SharedJson.Obj(item, "case");
                var rng = new SeededRandom((uint)SharedJson.Long(c, "seed"));
                var unlocked = c["unlocked"] is List<object> u ? new HashSet<string>(u.Cast<string>()) : null;
                var locked = c["locked"] is List<object> l ? l.Select(o => o as string).ToArray() : null;
                var boardHas = SharedJson.Bool(c, "boardHasGuaranteedCategory");
                foreach (var expectedRoll in SharedJson.Arr(c, "expectedOffers"))
                {
                    var expected = ((List<object>)expectedRoll).Select(o => o as string).ToArray();
                    CollectionAssert.AreEqual(expected, GearShop.Roll(rng, catalog, config, unlocked, locked, boardHas), SharedJson.Str(c, "id"));
                }
            }
        }

        [Test]
        public void ShopNeverOffersPowerCoresAndRespectsCopyCap()
        {
            var catalog = SharedDataLoader.LoadGears(Read("gears/starter_gears.json"));
            var config = SharedDataLoader.LoadShop(Read("economy/shop.json"));
            var rng = new SeededRandom(777);
            for (var i = 0; i < 500; i++)
            {
                var offers = GearShop.Roll(rng, catalog, config);
                Assert.IsFalse(offers.Contains("core.wayfarer"));
                Assert.IsTrue(offers.GroupBy(o => o).All(g => g.Count() <= config.MaxCopiesPerOffer));
            }
        }

        [Test]
        public void WaveDirectorMatchesSharedSchedule()
        {
            var mission = SharedDataLoader.LoadMission(Read("waves/mission_001.json"));
            var enemies = SharedDataLoader.LoadEnemies(Read("enemies/enemies.json"));
            var fixture = Fixture("mission_001_spawns.json");
            var waves = SharedJson.Arr(fixture, "waves");
            Assert.AreEqual(waves.Count, mission.Waves.Count);
            for (var w = 0; w < waves.Count; w++)
            {
                var expected = SharedJson.Arr(SharedJson.Obj(waves[w], "wave"), "spawns").Select(s =>
                {
                    var spawn = SharedJson.Obj(s, "spawn");
                    return $"{SharedJson.Int(spawn, "tick")}:{SharedJson.Int(spawn, "lane")}:{SharedJson.Str(spawn, "enemyId")}";
                }).ToArray();
                var actual = WaveDirector.Schedule(mission.Waves[w]).Select(s => $"{s.Tick}:{s.Lane}:{s.EnemyId}").ToArray();
                CollectionAssert.AreEqual(expected, actual, mission.Waves[w].Id);
                Assert.AreEqual(expected.Length, WaveDirector.Build(mission.Waves[w], enemies).Spawns.Count);
            }
        }

        private static BattlePhase PlaySharedWaveOne(params int[] pressLanes)
        {
            var mission = SharedDataLoader.LoadMission(Read("waves/mission_001.json"));
            var enemies = SharedDataLoader.LoadEnemies(Read("enemies/enemies.json"));
            var all = new[] { Direction.North, Direction.East, Direction.South, Direction.West };
            var board = new GearBoard();
            board.TryPlace(new GearNode("core", GearKind.Core, 2, 2, all), out _);
            var cells = new[] { (1, 2), (3, 2), (2, 1) };
            for (var i = 0; i < pressLanes.Length; i++)
                board.TryPlace(new GearNode($"press-{i}", GearKind.Output, cells[i].Item1, cells[i].Item2, all, 90,
                    outputKind: GearOutputKind.SpawnInfantry, targetLane: pressLanes[i]), out _);
            var session = new BattleSession(board, GearNetwork.Rebuild(board), WaveDirector.Build(mission.Waves[0], enemies));
            session.Start();
            for (var tick = 0; tick < 30 * 120 && session.Phase == BattlePhase.Combat; tick++) session.Tick();
            return session.Phase;
        }

        [Test]
        public void SharedWaveOneLosesWhenSideLanesAreUndefended()
        {
            // Design pressure: one press plus an idle hero cannot cover three lanes.
            Assert.AreEqual(BattlePhase.Defeat, PlaySharedWaveOne(1));
        }

        [Test]
        public void SharedWaveOneWinsWhenPressesCoverSideLanes()
        {
            Assert.AreEqual(BattlePhase.Victory, PlaySharedWaveOne(0, 2));
        }

        [Test]
        public void CombatScenariosMatchSharedTraces()
        {
            var results = CombatScenarioRunner.RunAll(Read("test-fixtures/combat_scenarios.json"), Read("waves/mission_001.json"), Read("enemies/enemies.json"));
            var expected = SharedJson.Arr(Fixture("combat_traces.json"), "results").Select(r => SharedJson.Obj(r, "result")).ToArray();
            Assert.AreEqual(expected.Length, results.Count);
            for (var i = 0; i < expected.Length; i++)
            {
                var e = expected[i];
                var r = results[i];
                Assert.AreEqual(SharedJson.Str(e, "id"), r.Id);
                Assert.AreEqual(SharedJson.Str(e, "phase"), r.Phase, r.Id);
                Assert.AreEqual(SharedJson.Int(e, "elapsedTicks"), r.ElapsedTicks, r.Id);
                Assert.AreEqual(SharedJson.Int(e, "fortressHealth"), r.FortressHealth, r.Id);
                Assert.AreEqual((uint)SharedJson.Long(e, "traceHash"), r.TraceHash, r.Id);
            }
        }

        [Test]
        public void JsonReaderRejectsMalformedInput()
        {
            Assert.Throws<System.FormatException>(() => SharedJson.Parse("{\"a\":1,}"));
            Assert.Throws<System.FormatException>(() => SharedJson.Parse("{\"a\":1,\"a\":2}"));
            Assert.Throws<System.FormatException>(() => SharedJson.Parse("[1 2]"));
            Assert.AreEqual(-3L, SharedJson.Parse("-3"));
        }
    }
}
